{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE or REPLACE TABLE snitch_db.maplemonk.grn_issues_joined as WITH voucher_base AS ( SELECT LOWER( REGEXP_REPLACE( CONCAT( COALESCE(GRN_PREFIX,\'\'), \'-\', COALESCE(TO_VARCHAR(TRUNC(GRN_NUMBER)), \'\') ), \'[^a-z0-9]+\', \'\' ) ) || \'|\' || REGEXP_REPLACE( REGEXP_REPLACE(LOWER(COALESCE(TO_PARTY,\'\')), \'snitch\', \'\'), \'[^a-z0-9]+\', \'\' ) AS RFID_JOIN_KEY, CASE WHEN COALESCE(QUANTITY, 0) = 0 THEN \'GRN Pending\' ELSE \'GRN Done\' END AS GRN_STATUS, * FROM snitch_db.maplemonk.logic_purchase_voucher ), issue_base AS ( SELECT CREATED_AT_DATE, UPDATED_AT_DATE, EVIDENCE_WITH_HTTPS, ID AS ISSUE_ID, QTY AS ISSUE_QTY, SKU, \"Issue\" as ISSUE, VENDOR AS VENDOR_ISSUE, COMMENTS, EVIDENCE, PO_NUMBER, SUB_ISSUE, CREATED_AT AS ISSUE_CREATED_AT, CREATED_BY, INVOICE_NUMBER, LAST_UPDATED_AT AS ISSUE_LAST_UPDATED_AT FROM snitch_db.maplemonk.issues_factory_sorted ), severity_map AS ( SELECT * FROM VALUES (\'Shade variations\', 10), (\'Double barcode\', 9), (\'Shortage/Excess\', 9), (\'Size mismatch\', 9), (\'Costing issues\', 8), (\'Wrong barcode\', 7), (\'Without barcode\', 7), (\'Packing conditions not as per SOP\', 6), (\'Relevant documents not available (QC docs / CAD file / packing list etc.)\', 5), (\'Costing not matching with invoice\', 5), (\'Qty mismatch (QC report vs invoice qty)\', 5), (\'Invoice issues (size-level missing / PO number missing / SKU missing)\', 4), (\'PO issues (expired / not available / entity names mismatch)\', 3) AS severity_map (SUB_ISSUE_RAW, SEVERITY) ), severity_norm AS ( SELECT LOWER(REGEXP_REPLACE(SUB_ISSUE_RAW, \'[^a-z0-9]+\', \'\')) AS SUB_ISSUE_KEY, SEVERITY FROM severity_map ), rfid_base AS ( SELECT LOWER(REGEXP_REPLACE(COALESCE(CAST(\"Doc No\" AS VARCHAR), \'\'), \'[^a-z0-9]+\', \'\')) || \'|\' || REGEXP_REPLACE( REGEXP_REPLACE(LOWER(COALESCE(CAST(\"Site Name\" AS VARCHAR),\'\')), \'snitch\', \'\'), \'[^a-z0-9]+\', \'\' ) AS RFID_JOIN_KEY, \"Doc Date\" AS DOC_DATE, \"Doc No\" AS DOC_NO, \"Site Name\" AS SITE_NAME, \"Matching Status\" AS MATCHING_STATUS, \"Scanning Status\" AS SCANNING_STATUS FROM snitch_db.maplemonk.s3_rfid_inward WHERE \"Matching Status\" IS NOT NULL ) SELECT v.*, CASE WHEN LOWER(i.CREATED_BY) IN (\'punit.c@snitch.com\',\'akash.s@snitch.com\') THEN \'SAPL-NORTH-TAURU\' WHEN LOWER(i.CREATED_BY) IN ( \'inward.erp.warehouse@snitch.com\', \'gopal.k@snitch.com\', \'guramma.s@snitch.com\', \'hemanth.t@snitch.com\', \'nitin.m@snitch.com\' ) THEN \'SAPL-WH2\' ELSE NULL END AS BRANCH_SHORT_NAME_MAPPED, r.MATCHING_STATUS, r.SCANNING_STATUS, r.DOC_NO, r.DOC_DATE, r.SITE_NAME, CASE WHEN r.MATCHING_STATUS IS NULL THEN NULL WHEN LOWER(r.MATCHING_STATUS) = \'pending\' THEN \'NON RFID\' ELSE \'RFID\' END AS RFID_STATUS, i.ISSUE_ID, i.CREATED_AT_DATE AS ISSUE_CREATED_AT_DATE, i.UPDATED_AT_DATE AS ISSUE_UPDATED_AT_DATE, i.EVIDENCE_WITH_HTTPS, i.ISSUE_QTY, i.SKU AS ISSUE_SKU, i.Issue, i.SUB_ISSUE, i.VENDOR_ISSUE, i.COMMENTS, i.EVIDENCE, i.PO_NUMBER AS PO_NUMBER_ISSUE, i.INVOICE_NUMBER AS ISSUE_INVOICE_NUMBER, i.ISSUE_CREATED_AT, i.CREATED_BY AS ISSUE_CREATED_BY, i.ISSUE_LAST_UPDATED_AT, COALESCE(s.SEVERITY, 0) AS ISSUE_SEVERITY, CASE WHEN i.ISSUE_ID IS NULL THEN 0 ELSE 1 END AS HAS_DISCREPANCY FROM voucher_base v LEFT JOIN issue_base i ON TRIM(CAST(v.LOT_NUMBER AS VARCHAR)) = TRIM(CAST(i.PO_NUMBER AS VARCHAR)) LEFT JOIN rfid_base r ON v.RFID_JOIN_KEY = r.RFID_JOIN_KEY LEFT JOIN severity_norm s ON LOWER(REGEXP_REPLACE(i.SUB_ISSUE, \'[^a-z0-9]+\', \'\')) = s.SUB_ISSUE_KEY;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            